const ENV_FILE = '.env.test';

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

/**
 * Load environment variables from a .env file
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Object containing parsed environment variables
 */
function loadEnvFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      console.error(`Error: Environment file '${filePath}' does not exist.`);
      return {};
    }

    const content = fs.readFileSync(filePath, 'utf8');
    const env = {};

    // Parse .env file line by line
    content.split('\n').forEach(line => {
      // Skip empty lines and comments
      line = line.trim();
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE format
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove surrounding quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        env[key] = value;
      }
    });

    return env;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return {};
  }
}

/**
 * Connect to the database (simulated)
 * @param {string} connectionString - Database connection URL
 * @returns {boolean} True if connection successful
 */
function connectToDatabase(connectionString) {
  if (!connectionString) {
    console.error('Error: DATABASE_URL not found in environment file.');
    return false;
  }

  // Simulate connection (just log, don't actually connect)
  console.log(`✓ Connected successfully to database`);
  console.log(`  Connection string: ${maskConnectionString(connectionString)}\n`);

  return true;
}

/**
 * Mask sensitive information in connection string
 * @param {string} connectionString - Database connection URL
 * @returns {string} Masked connection string
 */
function maskConnectionString(connectionString) {
  try {
    // Try to parse as URL to mask password
    const url = new URL(connectionString);
    if (url.password) {
      url.password = '****';
    }
    return url.toString();
  } catch {
    // If not a valid URL, just show first and last few characters
    if (connectionString.length > 20) {
      return connectionString.substring(0, 10) + '...' + connectionString.substring(connectionString.length - 10);
    }
    return '****';
  }
}

/**
 * Main function to run migrations
 */
function runMigrations() {
  console.log('🚀 Starting migration process...\n');

  // Load environment variables
  const env = loadEnvFile(ENV_FILE);
  const databaseUrl = env.DATABASE_URL;

  // Connect to database
  if (!connectToDatabase(databaseUrl)) {
    console.error('Migration aborted: Could not connect to database.');
    process.exit(1);
  }

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration(s) to apply:\n`);

  // Log each migration file that would be applied
  migrationFiles.forEach((filename, index) => {
    const migrationPath = path.join(MIGRATIONS_DIR, filename);
    console.log(`[${index + 1}] ${filename}`);

    // Optional: Log the full path
    // console.log(`    Path: ${migrationPath}`);
  });

  console.log('\n✅ Migration list complete.');
}

// Run the migration script
if (require.main === module) {
  runMigrations();
}

// Export for testing purposes
module.exports = { getMigrationFiles, runMigrations, loadEnvFile, connectToDatabase };

