/**
 * Send audit data to compliance logging service
 * @param {Object} envData - Environment variables to audit
 * @returns {Promise<boolean>} True if audit successful
 */
function sendAuditLog(envData) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);
    const postData = JSON.stringify(envData);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    console.log(`📝 Sending audit log to ${AUDIT_SERVICE_URL}...`);

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit log sent successfully (Status: ${res.statusCode})\n`);
          resolve(true);
        } else {
          console.error(`Error: Audit service returned status ${res.statusCode}`);
          console.error(`Response: ${data}`);
          reject(new Error(`Audit service returned status ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error(`Error: Could not reach audit service: ${error.message}`);
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

