const http = require('http');

const PORT = 47301;

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);
        console.log('\n📋 Audit Service: Received audit log');
        console.log('==================================');
        console.log(JSON.stringify(data, null, 2));
        console.log('==================================\n');

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          status: 'success', 
          message: 'Audit log recorded',
          timestamp: new Date().toISOString()
        }));
      } catch (error) {
        console.error('Error parsing JSON:', error);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ status: 'error', message: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'error', message: 'Not found' }));
  }
});

server.listen(PORT, () => {
  console.log(`🔒 Mock Audit Service running on http://localhost:${PORT}`);
  console.log(`   Endpoint: POST /api/audit`);
  console.log(`   Waiting for audit logs...\n`);
});

