const { spawn } = require('child_process');

console.log('🧪 Starting integration test...\n');

// Start audit service
console.log('Starting audit service...');
const auditService = spawn('node', ['audit-service.js']);

auditService.stdout.on('data', (data) => {
  console.log(`[Audit Service] ${data.toString().trim()}`);
});

auditService.stderr.on('data', (data) => {
  console.error(`[Audit Service Error] ${data.toString().trim()}`);
});

// Wait for service to be ready, then run migration
setTimeout(() => {
  console.log('\nRunning migration script...\n');
  const migration = spawn('node', ['migrate.js']);

  migration.stdout.on('data', (data) => {
    console.log(data.toString().trim());
  });

  migration.stderr.on('data', (data) => {
    console.error(data.toString().trim());
  });

  migration.on('close', (code) => {
