    const sqlFiles = files.filter(file => file.toLowerCase().endsWith('.sql'));

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in the migrations directory.');
      return [];
    }

    // Sort files alphabetically (common convention for migrations)
    // This ensures migrations like 001_init.sql, 002_users.sql, etc. run in order
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

/**
 * Main function to run migrations
 */
async function runMigrations() {
