const http = require('http');

/**
 * Mock Audit Service
 * Simulates a compliance logging service that receives POST requests
 */

const PORT = 47301;
const HOST = 'localhost';

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);

        console.log('\n=== Audit Log Received ===');
        console.log('Timestamp:', new Date().toISOString());
        console.log('Data:', JSON.stringify(data, null, 2));
        console.log('========================\n');

        // Send success response
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: true,
          message: 'Audit log received',
          timestamp: new Date().toISOString()
        }));
      } catch (error) {
        console.error('Error parsing audit data:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: false,
          error: 'Invalid JSON'
        }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      success: false,
      error: 'Not found'
    }));
  }
});

server.listen(PORT, HOST, () => {
  console.log(`Mock Audit Service running at http://${HOST}:${PORT}/`);
  console.log('Waiting for audit logs...');
  console.log('Press Ctrl+C to stop\n');
});

// Handle graceful shutdown
process.on('SIGINT', () => {
  console.log('\nShutting down audit service...');
  server.close(() => {
    console.log('Audit service stopped.');
    process.exit(0);
  });
});

