/**
 * Mask password in connection string for safe logging
 * @param {string} url - Database URL
 * @returns {string} URL with masked password
 */
function maskPassword(url) {
  try {
    // Match pattern: protocol://user:password@host/database
    // Look for :// then find the last @ before any /
    const protocolEnd = url.indexOf('://');
    if (protocolEnd === -1) {
      return url;
    }

    const afterProtocol = url.substring(protocolEnd + 3);
    const pathStart = afterProtocol.indexOf('/');
    const hostPart = pathStart === -1 ? afterProtocol : afterProtocol.substring(0, pathStart);
    const pathPart = pathStart === -1 ? '' : afterProtocol.substring(pathStart);

    // Find the last @ in the host part (in case password contains @)
    const lastAtIndex = hostPart.lastIndexOf('@');
    if (lastAtIndex === -1) {
      return url; // No authentication in URL
    }

    const authPart = hostPart.substring(0, lastAtIndex);
    const hostOnlyPart = hostPart.substring(lastAtIndex);

    // Find the colon separating username and password
    const colonIndex = authPart.indexOf(':');
    if (colonIndex === -1) {
      return url; // No password in URL
    }

    const username = authPart.substring(0, colonIndex);
    const maskedAuth = username + ':****';

    return url.substring(0, protocolEnd + 3) + maskedAuth + hostOnlyPart + pathPart;
  } catch (error) {
    return '[URL PARSE ERROR]';
  }
}

