  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      console.log('=== Audit Log Received ===');
      console.log('Timestamp:', new Date().toISOString());
      console.log('Data:', JSON.stringify(JSON.parse(body), null, 2));
      console.log('========================\n');

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ success: true, message: 'Audit log recorded' }));
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(PORT, () => {
  console.log(`Mock audit service running on http://localhost:${PORT}`);
