  if (req.url === '/api/audit' && req.method === 'POST') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);
        console.log('\n=== AUDIT LOG RECEIVED ===');
        console.log('Timestamp:', new Date().toISOString());
