  console.log(`Mock Audit Service running on http://localhost:${PORT}`);
  console.log(`Listening for POST requests to /api/audit\n`);
});

process.on('SIGINT', () => {
  console.log('\n\nShutting down audit service...');
  server.close();
  process.exit(0);
});

