 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

/**
 * Load environment variables from .env.test file
 * @returns {Object} Object containing parsed environment variables
 */
function loadEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.error(`Error: Environment file '${ENV_FILE}' does not exist`);
      return {};
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const envVars = {};

    // Parse .env file line by line
    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      line = line.trim();
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE pairs
      const separatorIndex = line.indexOf('=');
      if (separatorIndex !== -1) {
        const key = line.substring(0, separatorIndex).trim();
        let value = line.substring(separatorIndex + 1).trim();

        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) || 
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error('Error reading environment file:', error.message);
    return {};
  }
}

/**
 * Connect to the database (simulated)
 * @param {string} databaseUrl - The database connection string
 * @returns {boolean} True if connection successful
 */
function connectToDatabase(databaseUrl) {
  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in environment file');
    return false;
  }

  // Simulate connection (just log the message)
  console.log('✓ Connected successfully to database');
  console.log(`  Connection string: ${databaseUrl}\n`);
  return true;
}

/**
 * Get all SQL files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted alphabetically
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist`);
      return [];
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort(); // Sorts alphabetically, which works well with timestamp-prefixed filenames

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    return [];
  }
}

/**
 * Main function to run migrations
 */
function runMigrations() {
  console.log('=== Database Migration Script ===\n');

  // Load environment variables
  const envVars = loadEnvFile();
  const databaseUrl = envVars.DATABASE_URL;

  // Connect to database
  if (!connectToDatabase(databaseUrl)) {
    console.log('Migration aborted due to connection failure.');
    process.exit(1);
