const http = require('http');

const PORT = 47301;

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      console.log('\n=== Audit Service Received ===');
      console.log('Method:', req.method);
      console.log('URL:', req.url);
      console.log('Headers:', JSON.stringify(req.headers, null, 2));
      console.log('Body:', body);

      try {
        const data = JSON.parse(body);
        console.log('\nParsed Data:');
        console.log(JSON.stringify(data, null, 2));
      } catch (e) {
        console.log('Could not parse JSON');
      }

      console.log('================================\n');

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'success', message: 'Audit log received' }));
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(PORT, () => {
  console.log(`Mock Audit Service running on http://localhost:${PORT}`);
  console.log('Waiting for audit requests...\n');
});

