#!/usr/bin/env node

const { spawn } = require('child_process');

console.log('=== Testing Migration Script with Audit Service ===\n');

// Start the mock audit service
console.log('1. Starting mock audit service...');
const auditService = spawn('node', ['mock-audit-service.js']);

let auditOutput = '';

auditService.stdout.on('data', (data) => {
  auditOutput += data.toString();
  process.stdout.write(`[AUDIT] ${data}`);
});

auditService.stderr.on('data', (data) => {
  process.stderr.write(`[AUDIT ERROR] ${data}`);
});

// Wait for service to start, then run migrations
setTimeout(() => {
  console.log('\n2. Running migration script...\n');

  const migration = spawn('node', ['migrate.js']);

  migration.stdout.on('data', (data) => {
    process.stdout.write(data);
  });

  migration.stderr.on('data', (data) => {
    process.stderr.write(data);
  });

  migration.on('close', (code) => {
    console.log(`\n3. Migration script exited with code ${code}`);

    // Kill audit service
    auditService.kill();

    setTimeout(() => {
      console.log('\n=== Test Complete ===');
      process.exit(code);
    }, 500);
  });
}, 1000);

// Cleanup on exit
process.on('SIGINT', () => {
  auditService.kill();
  process.exit();
});

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = './migrations';

/**
 * Get all SQL files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted alphabetically
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      process.exit(1);
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only and sort them
    const sqlFiles = files
      .filter(file => file.toLowerCase().endsWith('.sql'))
      .sort(); // Sort alphabetically (convention: 001_create_users.sql, 002_add_posts.sql, etc.)

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Main function to run migrations
 */
function runMigrations() {
  console.log('Starting migration process...\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each migration file that would be applied
  migrationFiles.forEach((filename, index) => {
    console.log(`[${index + 1}] ${filename}`);
  });

  console.log('\nMigration listing complete.');
}

// Run the script
if (require.main === module) {
  runMigrations();
}

module.exports = { getMigrationFiles, runMigrations };

