const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Load environment variables from .env.test file
 * @returns {Object} Object containing parsed environment variables
 */
function loadEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.error(`Error: Environment file '${ENV_FILE}' does not exist`);
      return {};
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
    const envVars = {};

    // Parse .env file line by line
    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      line = line.trim();
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE format
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return {};
  }
}

/**
 * Connect to the database (simulated)
 * @param {string} databaseUrl - Database connection string
 * @returns {boolean} True if connection is successful
 */
function connectToDatabase(databaseUrl) {
  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in environment file');
    return false;
  }

  // Log successful connection (simulated)
  console.log('✓ Successfully connected to database');
  console.log(`  Connection string: ${maskConnectionString(databaseUrl)}\n`);
  return true;
}

/**
 * Mask sensitive information in connection string
 * @param {string} connectionString - Database connection string
 * @returns {string} Masked connection string
 */
function maskConnectionString(connectionString) {
  // Mask password in connection string (e.g., postgresql://user:password@host:port/db)
  return connectionString.replace(/:([^:@]+)@/, ':****@');
}

/**
 * Send audit log to the compliance service
 * @param {Object} envVars - Environment variables to audit
 * @returns {Promise<boolean>} True if audit was successful
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);
    const postData = JSON.stringify(envVars);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    console.log('📋 Sending configuration to audit service...');
    console.log(`   Endpoint: ${AUDIT_SERVICE_URL}\n`);

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✓ Audit log sent successfully');
          console.log(`   Status: ${res.statusCode}\n`);
          resolve(true);
        } else {
          console.error(`✗ Audit service returned error: ${res.statusCode}`);
          console.error(`   Response: ${data}\n`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.error(`✗ Failed to send audit log: ${error.message}`);
      console.error(`   Could not connect to ${AUDIT_SERVICE_URL}\n`);
      resolve(false);
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Get all SQL files from the migrations directory
 * @returns {string[]} Array of SQL filenames sorted alphabetically
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist`);
      return [];
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort(); // Sort alphabetically (which works well for timestamp-prefixed files)

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Main function to run migrations
 */
async function runMigrations() {
  console.log('=== Database Migration Script ===\n');

  // Load environment variables
  const envVars = loadEnvFile();
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in environment file');
    console.log('Aborting migration due to missing configuration.');
    process.exit(1);
  }

  // Send audit log for compliance
  const auditSuccess = await sendAuditLog(envVars);
  if (!auditSuccess) {
    console.error('Error: Failed to send audit log to compliance service');
    console.log('Aborting migration due to audit failure.');
    process.exit(1);
  }

  // Connect to database
  if (!connectToDatabase(databaseUrl)) {
    console.log('Aborting migration due to connection error.');
    process.exit(1);
  }

  console.log(`Looking for migrations in: ${MIGRATIONS_DIR}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration(s) to apply:\n`);

  migrationFiles.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });

  console.log('\n=== Migration scan complete ===');
}

// Run the migration script
runMigrations();

